-- ============================================================
-- 031_ielts_reading_strategy_lessons.sql
-- The 15 strategy / question-type chapters from "IELTS Reading Band
-- 5.5 to 8" -- 6 lessons under IELTS > Reading > Strategies, and 9
-- lessons across the (newly added) Question Types subtopics. Pure
-- teaching content; the book's exercises are covered separately by
-- the 5 full practice tests (029_ielts_reading_practice_tests.sql),
-- which is where the auto-graded interactive practice lives.
-- ============================================================

do $$
declare
  v_strategies uuid;
  v_true_false_not_given uuid;
  v_yes_no_not_given uuid;
  v_completion uuid;
  v_matching_headings uuid;
  v_matching_information uuid;
  v_matching_features uuid;
  v_multiple_choice uuid;
  v_short_answer_diagram_labelling uuid;
  v_lesson uuid;
begin
  select cn.id into v_strategies from content_nodes cn
    join content_nodes reading on cn.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and cn.slug = 'strategies';

  select cn.id into v_true_false_not_given from content_nodes cn
    join content_nodes qt on cn.parent_id = qt.id
    join content_nodes reading on qt.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and qt.slug = 'question-types' and cn.slug = 'true-false-not-given';

  select cn.id into v_yes_no_not_given from content_nodes cn
    join content_nodes qt on cn.parent_id = qt.id
    join content_nodes reading on qt.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and qt.slug = 'question-types' and cn.slug = 'yes-no-not-given';

  select cn.id into v_completion from content_nodes cn
    join content_nodes qt on cn.parent_id = qt.id
    join content_nodes reading on qt.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and qt.slug = 'question-types' and cn.slug = 'completion';

  select cn.id into v_matching_headings from content_nodes cn
    join content_nodes qt on cn.parent_id = qt.id
    join content_nodes reading on qt.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and qt.slug = 'question-types' and cn.slug = 'matching-headings';

  select cn.id into v_matching_information from content_nodes cn
    join content_nodes qt on cn.parent_id = qt.id
    join content_nodes reading on qt.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and qt.slug = 'question-types' and cn.slug = 'matching-information';

  select cn.id into v_matching_features from content_nodes cn
    join content_nodes qt on cn.parent_id = qt.id
    join content_nodes reading on qt.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and qt.slug = 'question-types' and cn.slug = 'matching-features';

  select cn.id into v_multiple_choice from content_nodes cn
    join content_nodes qt on cn.parent_id = qt.id
    join content_nodes reading on qt.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and qt.slug = 'question-types' and cn.slug = 'multiple-choice';

  select cn.id into v_short_answer_diagram_labelling from content_nodes cn
    join content_nodes qt on cn.parent_id = qt.id
    join content_nodes reading on qt.parent_id = reading.id
    join content_nodes ielts on reading.parent_id = ielts.id
    where ielts.slug = 'ielts' and reading.slug = 'reading' and qt.slug = 'question-types' and cn.slug = 'short-answer-and-diagram-labelling';

  -- How the IELTS Reading Test Works
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_strategies, 'How the IELTS Reading Test Works', 'how-the-test-works', 'Test structure, the question types you''ll meet, and how Band Score is calculated.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"ভূমিকা — কেন তুমি বারবার ৫.৫-এ আটকে যাচ্ছ"}]},{"type":"paragraph","content":[{"type":"text","text":"এই বইটা লেখার আগে আমি একটা জিনিস লক্ষ করেছি যেটা প্রায় প্রতিটা ৫.৫-এ আটকে থাকা শিক্ষার্থীর ক্ষেত্রে সত্যি: তারা ইংরেজি বোঝে না বলে কম নম্বর পায় না। তারা পরীক্ষাটা যেভাবে সাজানো, সেভাবে উত্তর করে না বলে কম নম্বর পায়।"}]},{"type":"paragraph","content":[{"type":"text","text":"চিন্তা করে দেখো — তুমি নিশ্চয়ই পুরো passage পড়তে পারো। বাংলায় অনুবাদ করে দিলে বেশিরভাগ প্রশ্নের উত্তর তুমি বলে দিতে পারবে। তাহলে সমস্যাটা কোথায়?"}]},{"type":"paragraph","content":[{"type":"text","text":"সমস্যা তিনটে জায়গায় — এবং তিনটাই ঠিক করা সম্ভব:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"সময়ের সাথে যুদ্ধ। ৬০ মিনিটে ৩টা passage আর ৪০টা প্রশ্ন — মানে প্রতি passage-এ মাত্র ২০ মিনিট। পুরো passage মনোযোগ দিয়ে পড়তে গেলে সময় শেষ হয়ে যায়, শেষ passage-এর প্রশ্নগুলো আন্দাজে করতে হয়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্নের ধরন না চেনা। True/False/Not Given আর Yes/No/Not Given দেখতে একরকম, কিন্তু কৌশল সম্পূর্ণ আলাদা। এই দুটো গুলিয়ে ফেলাই সবচেয়ে বেশি নম্বর হারানোর কারণ।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Paraphrase ধরতে না পারা। প্রশ্নে passage-এর হুবহু শব্দ থাকে না। \"increase\" প্রশ্নে থাকলে passage-এ থাকতে পারে \"rise\", \"grow\", \"climb\" — এই সংযোগ ধরতে না পারলে সঠিক জায়গা খুঁজে পাওয়াই যায় না।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"একটা সংখ্যা যা আশা জাগাবে ৪০টা প্রশ্নের মধ্যে ৩০টা সঠিক করলেই Band 7 হয়ে যায় (IELTS Academic Reading band table অনুযায়ী, সংস্করণভেদে সামান্য পার্থক্য হতে পারে)। মানে ১০টা প্রশ্ন ভুল হওয়ার অবকাশ আছে। তোমার লক্ষ্য নিখুঁত হওয়া নয় — লক্ষ্য হলো সঠিক কৌশলে সহজ প্রশ্নগুলো নিশ্চিতভাবে ধরা, এবং কঠিন প্রশ্নে সময় নষ্ট না করা।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"এই বইটি কীভাবে ব্যবহার করবে"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"বইয়ের নকশা"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Part"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বিষয়"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কী পাবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 1"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ভিত্তি"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পরীক্ষার গঠন, তোমার সমস্যা নির্ণয়, মূল কৌশল (skim, scan, predict, paraphrase, timing)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 2"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"True/False/NG ও Yes/No/NG"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে বেশি নম্বর-হারানো প্রশ্নের ধরন — সম্পূর্ণ আলাদা করে শেখানো হয়েছে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 3"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill-in-the-Gap ধরনসমূহ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sentence/Summary/Note/Table/Flow-chart completion, word limit-এর নিয়ম"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 4"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching প্রশ্ন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Heading matching, Information matching, Feature matching"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 5"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বাকি প্রশ্নের ধরন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Multiple Choice, Short Answer, Diagram Labelling"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 6"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৫টি সম্পূর্ণ Practice Test"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১৫টি passage, ২০০টি প্রশ্ন, প্রতিটি উত্তরের ব্যাখ্যাসহ Answer Key"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Part 7"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষ পাঠ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুলের প্যাটার্ন ধরা, ৩০ দিনের প্ল্যান, পরীক্ষার দিনের কৌশল"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"তিনটি নিয়ম"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটি strategy chapter আগে পড়ো, তারপর test attempt করো। কৌশল না জেনে practice test দিলে ভুল অভ্যাস তৈরি হয় — যা পরে ভাঙা কঠিন।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Timer ছাড়া কখনো practice কোরো না। Reading-এ সবচেয়ে বড় শত্রু সময়। প্রতিটি passage-এর জন্য ২০ মিনিট বেঁধে দাও, ঘড়ি দেখতে দেখতে অনুশীলন করো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুল উত্তর মিলিয়ে \"কেন ভুল হলো\" বোঝো, শুধু সঠিক উত্তর মুখস্থ কোরো না। প্রতিটি answer key-তে ব্যাখ্যা দেওয়া আছে — সেটা পড়ে নিজের ভুলের প্যাটার্ন ধরো (Part 7-এ এর জন্য একটা টেমপ্লেট আছে)।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"তিনটি অভ্যাস যা তোমাকে ৫.৫-এ আটকে রাখছে ❌ পুরো passage প্রথমে মনোযোগ দিয়ে পড়া। এতে সময় নষ্ট হয় সবচেয়ে বেশি। প্রশ্ন আগে দেখে, তারপর সেই তথ্য খুঁজে বের করাই (scanning) সঠিক পদ্ধতি। ❌ \"passage-এ শব্দটা নেই\" মানেই \"Not Given\" ধরে নেওয়া। Not Given মানে তথ্যটাই নেই, ভিন্ন শব্দে থাকতে পারে এমন নয়। এই ভুল ধারণাই সবচেয়ে বেশি নম্বর কাটে। ❌ একটা কঠিন প্রশ্নে ৩-৪ মিনিট আটকে থাকা। একটা প্রশ্নে বেশি সময় দিলে বাকি সহজ প্রশ্নগুলো করার সময় থাকে না। ৯০ সেকেন্ডে উত্তর না পেলে মার্ক করে পরেরটায় যাও।"}]}]},{"type":"paragraph","content":[{"type":"text","text":"PART 1"}]},{"type":"paragraph","content":[{"type":"text","text":"ভিত্তি"}]},{"type":"paragraph","content":[{"type":"text","text":"পরীক্ষার গঠন, তোমার সমস্যা নির্ণয়, এবং পাঁচটি মূল কৌশল"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১ — Reading Test: সম্পূর্ণ চিত্র"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১.১ গঠন"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Academic"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"General Training"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্যাসেজ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩টি (ক্রমশ কঠিন)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩টি বিভাগ (Section 1 সহজ, Section 3 কঠিন)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মোট শব্দ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"~২,১৫০–২,৭৫০"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"~২,০০০–২,৪০০"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৪০টি"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৪০টি"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সময়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৬০ মিনিট (অতিরিক্ত সময় নেই!)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৬০ মিনিট"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Answer Transfer"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তরপত্রে সরাসরি লেখো — আলাদা সময় নেই"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একই"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Listening থেকে বড় পার্থক্য Listening-এ answer sheet-এ তোলার জন্য ১০ মিনিট বাড়তি সময় থাকে। Reading-এ তা নেই — উত্তর সরাসরি answer sheet-এ লিখতে হয়, ৬০ মিনিটের মধ্যেই। তাই শেষ ২ মিনিট answer transfer-এর জন্য না রাখলে ভালো উত্তর জানা থাকা সত্ত্বেও ফাঁকা থেকে যেতে পারে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"t