  values (v_strategies, 'Find Your Weak Spot', 'find-your-weak-spot', 'Three common reading profiles -- work out which mistake is actually costing you marks.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ২ — তোমার সমস্যা ঠিক কোথায়"}]},{"type":"paragraph","content":[{"type":"text","text":"Band 5.5-এ আটকে থাকা শিক্ষার্থীদের মধ্যে মূলত তিন ধরনের প্রোফাইল দেখা যায়। নিজেকে চেনো — কারণ প্রতিটার সমাধান আলাদা।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.১ প্রোফাইল A — \"সময় শেষ হয়ে যায়\""}]},{"type":"paragraph","content":[{"type":"text","text":"তুমি প্রথম দুটো passage মোটামুটি ভালো করো, কিন্তু তৃতীয় passage-এ পৌঁছাতে পৌঁছাতে ১০ মিনিটও থাকে না। শেষ ১০-১২টা প্রশ্ন আন্দাজে করতে হয়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"লক্ষণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সমাধান কোথায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটা passage পুরোপুরি পড়ে ফেলো, তারপর প্রশ্নে যাও"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৩ — Scanning কৌশল"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা কঠিন প্রশ্নে ৩+ মিনিট আটকে থাকো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৩ — Time Management"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage 3-এ পৌঁছানোর আগেই ৪৫ মিনিট শেষ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৩ — ২০-মিনিট নিয়ম"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.২ প্রোফাইল B — \"সময় আছে, কিন্তু ভুল হয়\""}]},{"type":"paragraph","content":[{"type":"text","text":"তুমি সময়মতো শেষ করতে পারো, প্রতিটা প্রশ্নের উত্তরও দাও — কিন্তু ২৫টার বেশি সঠিক হয় না। বিশেষ করে True/False/Not Given আর Matching-এ বেশি ভুল হয়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"লক্ষণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সমাধান কোথায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Not Given\" আর \"False\" গুলিয়ে ফেলো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৪ — True/False/Not Given"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"লেখকের মতামত আর তথ্য গুলিয়ে ফেলো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৫ — Yes/No/Not Given"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Heading-এ একই heading দুইবার ব্যবহার করে ফেলো"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৯ — Matching Headings"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill-in-the-gap-এ word limit ভেঙে ফেলো (যেমন ONE WORD-এ দুই শব্দ লেখা)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৭ — Completion-এর নিয়ম"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.৩ প্রোফাইল C — \"নির্দিষ্ট জায়গা খুঁজে পাই না\""}]},{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন পড়ে বুঝি কী চাইছে, কিন্তু passage-এ কোথায় উত্তর আছে খুঁজে পেতে পেতেই অনেক সময় চলে যায়।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"লক্ষণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সমাধান কোথায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্নের শব্দ passage-এ হুবহু খুঁজি, পাই না"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৩ — Paraphrase Recognition"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সংখ্যা, তারিখ, নাম চিনতে সময় লাগে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৩ — Scanning Anchors"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একই তথ্য দুই জায়গায় মনে হয়, কোনটা সঠিক বুঝি না"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অধ্যায় ৪ ও ৭ — Location Confirmation"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"বেশিরভাগ শিক্ষার্থী আসলে তিনটাই কিছুটা করে একটাতে ১০০% পড়ে ফেলার দরকার নেই। যে প্রোফাইলের লক্ষণ সবচেয়ে বেশি মিলছে, সেই অধ্যায়গুলো প্রথমে দুইবার পড়ো — বাকিগুলো স্বাভাবিক ক্রমেই আসবে।"}]}]}]}'::jsonb, 'published', 'advanced', 8, now());

