  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_true_false_not_given, 'True / False / Not Given', 'true-false-not-given-strategy', 'What this question type really tests, the five-step method, and the words to watch for.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৪ — True / False / Not Given"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.১ এই প্রশ্ন আসলে কী মাপে"}]},{"type":"paragraph","content":[{"type":"text","text":"এই ধরনের প্রশ্নে একটা statement দেওয়া থাকে, এবং passage-এর তথ্যের (fact) সাথে সেটা মিলিয়ে দেখতে হয়। এটা লেখকের মতামত নয় — এখানে সবসময় যাচাইযোগ্য তথ্য থাকে (সংখ্যা, ঘটনা, প্রক্রিয়া, ইতিহাস)।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অর্থ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"TRUE"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement-টি passage-এর তথ্যের সাথে সম্পূর্ণ মেলে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"FALSE"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement-টি passage-এর তথ্যের বিপরীত — passage স্পষ্টভাবে উল্টো কথা বলছে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"NOT GIVEN"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এই তথ্য passage-এ কোথাও নেই — না সমর্থন করে, না অস্বীকার করে"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে বড় ভুল ধারণা — এখানেই সবচেয়ে বেশি নম্বর কাটা যায় \"passage-এ এই শব্দটা খুঁজে পাচ্ছি না\" ≠ Not Given। তথ্যটা ভিন্ন শব্দে (paraphrase) থাকতে পারে। Not Given শুধু তখনই, যখন পুরো বিষয়টা নিয়েই passage কিছু বলেনি — না সরাসরি, না ঘুরিয়ে। \"passage আংশিক সমর্থন করছে\" ≠ True। Statement-এর প্রতিটা অংশ পুরোপুরি মিলতে হবে। একটা অংশ ভুল থাকলে পুরো statement False বা Not Given হয়ে যেতে পারে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.২ পাঁচ ধাপের পদ্ধতি"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement-টা মনোযোগ দিয়ে পড়ো, প্রতিটা অংশ আলাদা করো। একাধিক তথ্য একসাথে থাকলে প্রতিটা যাচাই করতে হবে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keyword চিহ্নিত করো — বিশেষত সংখ্যা, নাম, বছর, বা নির্দিষ্ট বিশেষ্য (noun)। এগুলো দিয়েই passage-এ জায়গা খুঁজে পাবে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ সেই keyword বা তার paraphrase স্ক্যান করো — পুরো passage না পড়ে শুধু সেই অংশ খুঁজো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement আর passage-এর বাক্য পাশাপাশি রেখে তুলনা করো — বিশেষভাবে negation (not, no, never), qualifier (all, some, most, always, only), এবং comparison শব্দ (more, less, better) খেয়াল করো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"সিদ্ধান্ত নাও: পুরোপুরি মিললে True, স্পষ্ট বিপরীত হলে False, কোনো তথ্যই না থাকলে Not Given।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.৩ Worked Example"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"একই Passage, তিনটি ভিন্ন উত্তর Passage অংশ: \"The Wright brothers made their first powered flight in 1903, though earlier attempts by other inventors had failed to sustain controlled flight for more than a few seconds.\"  Statement ১: The Wright brothers were the first people to attempt powered flight. → Passage বলছে \"earlier attempts by other inventors\" — অর্থাৎ Wright brothers-এর আগেও অন্যরা চেষ্টা করেছিল। Statement বলছে তারাই প্রথম চেষ্টাকারী — এটা passage-এর তথ্যের বিপরীত। উত্তর: FALSE  Statement ২: The Wright brothers'' flight took place in the early twentieth century. → 1903 = বিংশ শতাব্দীর শুরুর দিক। সংখ্যা মিলছে, তথ্য সঠিক। উত্তর: TRUE  Statement ৩: The Wright brothers received funding from the government. → Passage-এ funding নিয়ে কোনো তথ্যই নেই — না হ্যাঁ, না না। উত্তর: NOT GIVEN"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.৪ যে শব্দগুলো বিশেষভাবে খেয়াল রাখবে"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ শব্দ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কেন গুরুত্বপূর্ণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Negation"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"not, no longer, without, unless, rarely"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা \"not\" পুরো অর্থ উল্টে দেয়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Absolute Qualifier"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"all, every, always, only, never, none"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ \"most\" থাকলে আর statement-এ \"all\" থাকলে — প্রায়ই False"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Partial Qualifier"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"some, most, many, often, generally"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Absolute-এর সাথে গুলিয়ে ফেললে ভুল হয়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Comparison"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"more than, less than, as ... as, better, worse"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সংখ্যা বা তুলনা ভুল হলে পুরো statement False"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"একটা দ্রুত পরীক্ষা Passage-এ লেখা \"Most students improved\" আর statement বলছে \"All students improved\" — এটা False, কারণ \"most\" ≠ \"all\"। এই ধরনের সূক্ষ্ম পার্থক্যই Band 5.5 আর Band 7-এর মধ্যে ফারাক গড়ে দেয়।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৪.৫ Not Given চেনার সহজ পরীক্ষা"}]},{"type":"paragraph","content":[{"type":"text","text":"নিজেকে জিজ্ঞেস করো: \"আমি কি passage-এর কোনো একটা নির্দিষ্ট বাক্য দেখিয়ে বলতে পারব এই statement সত্যি, বা এই statement মিথ্যা?\""}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"যদি পারো (statement সমর্থিত) → True"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"যদি পারো (statement অস্বীকৃত/বিপরীত) → False"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"যদি না পারো — কোনো বাক্যই এই নির্দিষ্ট দাবিটা নিয়ে কিছু বলছে না → Not Given"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"আরেকটা সাধারণ ফাঁদ সাধারণ জ্ঞান (common sense) দিয়ে উত্তর দিও না। \"সূর্য পূর্ব দিকে ওঠে\" এটা সত্যি জানলেও, passage যদি এটা উল্লেখ না করে, উত্তর Not Given। শুধু passage-এ যা লেখা আছে তার ভিত্তিতে উত্তর দাও, বাস্তব জ্ঞান দিয়ে নয়।"}]}]}]}'::jsonb, 'published', 'advanced', 12, now());

  -- Yes / No / Not Given
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_yes_no_not_given, 'Yes / No / Not Given', 'yes-no-not-given-strategy', 'How this differs from True/False/Not Given, and the extra step it requires.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৫ — Yes / No / Not Given"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.১ True/False/NG থেকে পার্থক্য — এটাই সবচেয়ে গুরুত্বপূর্ণ কথা"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"True/False/Not Given"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes/No/Not Given"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কী যাচাই করে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তথ্য (facts) — ঘটনা, সংখ্যা, প্রক্রিয়া"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"লেখকের মতামত/দাবি (claims) — লেখক কী মনে করেন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এর ধরন"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তথ্যভিত্তিক অংশ (objective)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যুক্তি বা মতামতভিত্তিক অংশ (argumentative)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"চেনার উপায়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সংখ্যা, তারিখ, প্রক্রিয়ার বর্ণনা বেশি থাকে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"লেখক \"argue\", \"believe\", \"suggest\", \"claim\" জাতীয় শব্দ ব্যবহার করেন"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"মনে রাখার সহজ উপায় True/False = \"এটা কি ঘটেছিল/সত্যি?\" (তথ্য)। Yes/No = \"লেখক কি এটা মনে করেন?\" (মতামত)। প্রশ্নের নির্দেশনায় (instructions) কোনটা জিজ্ঞেস করা হচ্ছে তা সবসময় লেখা থাকে — সেটা প্রথমেই পড়ে নিশ্চিত হও কোন ধরনের প্রশ্ন করছ।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.২ পদ্ধতি — True/False-এর মতোই, কিন্তু একটা বাড়তি ধাপ"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement পড়ে বুঝো এটা লেখকের কোন মতামত/দাবি প্রতিফলিত করছে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ লেখক ঠিক এই বিষয়ে কী বলেছেন খুঁজো — বিশেষত মতামত প্রকাশক শব্দের কাছাকাছি (argue, claim, suggest, believe, in my view, it is likely that)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"লেখকের মতামত আর অন্য কারো উদ্ধৃত মতামত গুলিয়ে ফেলো না — passage-এ প্রায়ই অন্য গবেষক/বিশেষজ্ঞের মত উদ্ধৃত করা হয়, যেটা লেখকের নিজের মত নাও হতে পারে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement লেখকের মতের সাথে মিললে Yes, বিপরীত হলে No, লেখক এই নির্দিষ্ট বিষয়ে কিছুই না বললে Not Given।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৩ Worked Example"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"লেখকের মত বনাম উদ্ধৃত মত Passage অংশ: \"While some economists argue that automation will inevitably lead to mass unemployment, this view oversimplifies a far more complex picture. History suggests that technological change, though disruptive in the short term, tends to create new categories of employment even as it eliminates others.\"  Statement ১: Automation will definitely cause widespread job losses. → লেখক নিজে এই মত সমর্থন করছেন না — বরং এটাকে \"oversimplifies\" বলে প্রত্যাখ্যান করছেন। এটা অন্য অর্থনীতিবিদদের মত, লেখকের নয়। উত্তর: NO  Statement ২: New types of jobs tend to emerge alongside technological change. → লেখক ঠিক এই কথাই বলছেন: \"tends to create new categories of employment\"। উত্তর: YES  Statement ৩: Governments should introduce policies to slow down automation. → Policy নিয়ে লেখক কিছুই বলেননি। উত্তর: NOT GIVEN"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৪ ফাঁদ চেনা: \"উদ্ধৃত মত\" বনাম \"লেখকের মত\""}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে সাধারণ ভুল Passage-এ প্রায়ই লেখা থাকে: \"Some critics argue that X...\" — এটা লেখকের মত নয়, এটা অন্যদের মত যা লেখক উল্লেখ করছেন মাত্র। লেখকের নিজের অবস্থান সাধারণত এর পরের বাক্যে আসে — বিশেষত \"however\", \"yet\", \"in fact\", \"but\" দিয়ে শুরু হওয়া বাক্যে। সবসময় \"but/however/yet\"-এর পরের অংশটা খোঁজো — ওখানেই আসল লেখকের মত লুকানো থাকে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৫ দ্রুত checklist — দুটো ধরন একসাথে গুলিয়ে গেলে"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"যদি প্রশ্নে থাকে"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"তাহলে বুঝবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"TRUE / FALSE / NOT GIVEN"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তথ্য যাচাই — সংখ্যা, তারিখ, প্রক্রিয়ার দিকে মনোযোগ দাও"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"YES / NO / NOT GIVEN"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মতামত যাচাই — লেখক কী বলছেন সেদিকে মনোযোগ দাও, অন্য কারো উদ্ধৃত মত নয়"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"মনে রাখবে — একই টেস্টে দুই ধরনের প্রশ্নই থাকতে পারে, ভিন্ন passage-এ বা এমনকি একই passage-এর ভিন্ন section-এ। প্রতিবার নতুন প্রশ্নের সেট শুরু করার আগে instructions আবার পড়ে নিশ্চিত হও কোন ধরনটা করছ।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৫.৬ মিনি অনুশীলন — নিজে চেষ্টা করো"}]},{"type":"paragraph","content":[{"type":"text","text":"নিচের ছোট অনুচ্ছেদটা পড়ে statement-গুলোর উত্তর নিজে বের করার চেষ্টা করো (উত্তর নিচে দেওয়া আছে)।"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"নিজে চেষ্টা করো Passage: \"Urban beekeeping has grown rapidly in cities across the world over the past decade. Proponents claim it helps pollinator populations recover, though some ecologists caution that concentrating too many honeybee colonies in small urban areas may actually compete with, rather than support, wild native bee species. The practice remains legal in most major cities, though several now require beekeepers to register their hives.\"  ১. Urban beekeeping has become more common in the last ten years. (True/False/NG) ২. All ecologists agree that urban beekeeping benefits wild bee populations. (True/False/NG) ৩. Registering hives is compulsory in every city that permits beekeeping. (True/False/NG) ৪. The author believes urban beekeeping should be banned. (Yes/No/NG) ৫. Concentrated honeybee populations might harm native bee species. (Yes/No/NG)"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সংক্ষিপ্ত ব্যাখ্যা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"TRUE"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"grown rapidly ... over the past decade\" — সরাসরি সমর্থিত"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"FALSE"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"some ecologists caution\" — সবাই একমত নয়, বরং দ্বিমত আছে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"NOT GIVEN"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"several now require\" — সব শহরে নয়, কিন্তু \"প্রতিটি\" শহরে বাধ্যতামূলক কিনা তা স্পষ্ট বলা নেই"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৪"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"NOT GIVEN"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"লেখক নিষিদ্ধ করার পক্ষে কিছু বলেননি — শুধু বিতর্কটা তুলে ধরেছেন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৫"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"YES"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"may actually compete with ... wild native bee species\" — এই সতর্কতা passage-এ স্পষ্টভাবে উপস্থাপিত"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"PART 3"}]},{"type":"paragraph","content":[{"type":"text","text":"Fill-in-the-Gap ধরনসমূহ"}]},{"type":"paragraph","content":[{"type":"text","text":"Sentence, Summary, Note, Table ও Flow-chart Completion — এবং Word Limit-এর নিয়ম"}]}]}'::jsonb, 'published', 'advanced', 12, now());

