  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_completion, 'Completion: Structure & Method', 'structure-and-method', 'The word-limit rule and a five-step method for sentence, summary, table, and flow-chart completion.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৬ — Completion প্রশ্নের সাধারণ কাঠামো"}]},{"type":"paragraph","content":[{"type":"text","text":"এই পরিবারের প্রশ্নগুলো (Sentence Completion, Summary Completion, Note Completion, Table Completion, Flow-chart Completion, Diagram Completion) দেখতে আলাদা মনে হলেও, কৌশল প্রায় একই। পার্থক্য শুধু তথ্যটা কীভাবে সাজানো আছে তাতে।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"দেখতে যেমন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sentence Completion"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আলাদা আলাদা অসম্পূর্ণ বাক্য, প্রতিটাতে একটা ফাঁকা জায়গা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Summary Completion"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পুরো passage-এর সারাংশ, কয়েকটা ফাঁকা জায়গাসহ একটা অনুচ্ছেদ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Note Completion"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বুলেট পয়েন্ট আকারে সংক্ষিপ্ত নোট, ফাঁকা জায়গাসহ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Table Completion"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তথ্য সারণী আকারে, কিছু ঘর ফাঁকা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Flow-chart Completion"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ধাপে ধাপে প্রক্রিয়া, তীরচিহ্ন দিয়ে সংযুক্ত, ফাঁকা জায়গাসহ"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৬.১ সবচেয়ে গুরুত্বপূর্ণ নিয়ম — Word Limit"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"এই নিয়ম ভাঙলে সঠিক উত্তরও বাতিল হয়ে যায় প্রতিটা Completion প্রশ্নের উপরে লেখা থাকে, যেমন \"NO MORE THAN TWO WORDS\" বা \"ONE WORD AND/OR A NUMBER\"। এই সীমা নির্দেশনা নয়, নিয়ম — সীমা ভাঙলে উত্তর সম্পূর্ণ সঠিক হলেও নম্বর কাটা যাবে। যেমন \"NO MORE THAN TWO WORDS\" মানে ১টা বা ২টা শব্দ লেখা যাবে, ৩টা নয়। \"a\", \"the\", \"and\" এই ছোট শব্দগুলোও গোনা হয়।"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"নির্দেশনা"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"যা করতে পারবে"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ONE WORD ONLY"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ঠিক ১টা শব্দ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"pollution ✓ · air pollution ✗ (২ শব্দ)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"NO MORE THAN TWO WORDS"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১ বা ২টা শব্দ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"climate change ✓ · rapid climate change ✗ (৩ শব্দ)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ONE WORD AND/OR A NUMBER"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১টা শব্দ, ১টা সংখ্যা, বা দুটো একসাথে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1990 ✓ · 20 percent ✓ · twenty percent ✗ (সংখ্যা বানানে লিখলে গোনা যায় ২ শব্দ হিসেবে, safest হলো ডিজিটে লেখা)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"NO MORE THAN THREE WORDS"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১, ২ বা ৩টা শব্দ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"renewable energy sources ✓"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"হাইফেনযুক্ত শব্দ নিয়ে একটা কৌশল Hyphenated শব্দ (যেমন \"well-being\", \"eco-friendly\") সাধারণত ১টা শব্দ হিসেবে গণনা হয় — কারণ passage-এ hyphen দিয়ে যেভাবে লেখা আছে সেভাবেই লিখলে নিরাপদ। সন্দেহ হলে passage-এ যেভাবে বানান আছে ঠিক সেভাবেই কপি করো, নিজে থেকে বানান পরিবর্তন কোরো না।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৬.২ পাঁচ ধাপের পদ্ধতি"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটা ফাঁকা জায়গার আগে-পরের শব্দ পড়ো — এটা বলে দেবে কোন ধরনের শব্দ বসবে (noun, verb, adjective, number)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Grammar থেকে আন্দাজ করো। ফাঁকার আগে \"a\" বা \"an\" থাকলে singular noun বসবে। ফাঁকার পরে verb থাকলে (যেমন \"___ increases\") তাহলে ফাঁকায় noun/subject বসবে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keyword দিয়ে passage-এ জায়গা খুঁজো — বাক্যের অন্য অংশের সাথে মিল থাকা শব্দ বা paraphrase খোঁজো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"সঠিক শব্দ বেছে নাও passage থেকে হুবহু — নিজে থেকে শব্দ তৈরি বা পরিবর্তন কোরো না, passage-এ যা লেখা ঠিক সেটাই ব্যবহার করো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Word limit ও grammar দুটোই আবার যাচাই করো — বসানো শব্দটা বাক্যে ব্যাকরণগতভাবে ঠিক বসছে কিনা দেখো।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৬.৩ Worked Example — Summary Completion"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"একটা Summary Completion কীভাবে সমাধান হয় Passage অংশ: \"Honeybee colonies communicate the location of food sources through an intricate series of movements known as the waggle dance. First described in detail by Karl von Frisch in the 1940s, this behaviour allows a single forager to convey both the direction and the approximate distance of a food source to the rest of the hive.\"  Summary: Bees use a movement pattern called the (26)........... to tell other bees where food is. This behaviour was first studied by (27)........... . The dance can show both the (28)........... and distance of a food source.  (NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer)  (26): waggle dance — passage-এ হুবহু \"waggle dance\" আছে, ২ শব্দ (27): Karl von Frisch — নাম হুবহু বসাতে হবে, capital letter খেয়াল করো (28): direction — \"convey both the direction and ... distance\" থেকে, \"distance\" প্রশ্নেই আছে তাই বাকি অংশ \"direction\""}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৬.৪ Table ও Flow-chart Completion-এর বাড়তি টিপস"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Table Completion প্রথমে টেবিলের হেডার (কলামের শিরোনাম) পড়ো — এটা বলে দেবে প্রতিটা কলামে কী ধরনের তথ্য (সময়, স্থান, সংখ্যা, বর্ণনা) আসবে। এতে ফাঁকা জায়গায় কী বসবে তা আগেই আন্দাজ করা যায়।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Flow-chart Completion তীরচিহ্নগুলো (arrows) ক্রম নির্দেশ করে — passage-এ ধাপগুলো সবসময় একই ক্রমে থাকে না, কিন্তু flow-chart-এর ক্রম অনুযায়ী passage-এ ধাপে ধাপে এগোলেই উত্তর পাওয়া যায়। একটা ধাপের উত্তর পেলে, পরের ফাঁকার উত্তর সাধারণত passage-এ তার পরেই থাকে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৬.৫ মিনি অনুশীলন"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"নিজে চেষ্টা করো Passage: \"Coffee cultivation began in the highlands of Ethiopia, where local legend credits its discovery to a goat herder named Kaldi, who noticed his goats becoming unusually energetic after eating berries from a certain shrub. By the fifteenth century, coffee had reached the Arabian Peninsula, where it was cultivated on a large scale for the first time and traded along regional routes.\"  Coffee was first discovered, according to legend, by a (1)........... in Ethiopia. He observed that his goats became more (2)........... after eating berries from a shrub. By the (3)........... century, coffee cultivation had spread to the Arabian Peninsula. (NO MORE THAN TWO WORDS for each answer)"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ব্যাখ্যা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"১"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"goat herder"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"a goat herder named Kaldi\" — পেশা জিজ্ঞেস করা হয়েছে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"২"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"energetic"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"unusually energetic\" — adjective, \"more\" দিয়ে বাক্য শুরু তাই শুধু adjective বসবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"৩"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"fifteenth"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"By the fifteenth century\" — হুবহু সংখ্যাবাচক শব্দ"}]}]}]}]}]}'::jsonb, 'published', 'advanced', 12, now());

