  values (v_completion, 'Completion: Common Mistakes & Speed', 'common-mistakes-and-speed', 'Five common mistakes in completion questions, and how to save time.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৭ — Completion-এর সাধারণ ভুল ও সমাধান"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৭.১ পাঁচটি সাধারণ ভুল"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুল"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"সমাধান"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Word limit ভেঙে ফেলা (২ শব্দের জায়গায় ৩ শব্দ লেখা)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর লেখার আগে নির্দেশনা আরেকবার পড়ো, লেখার পরেও গুনে দেখো"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এর বানান পরিবর্তন করে ফেলা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ যেভাবে লেখা ঠিক সেভাবেই কপি করো — spelling ভুল হলে নম্বর কাটা যায়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Singular/Plural ভুল করা (boy-এর জায়গায় boys বা উল্টো)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বাক্যের grammar দেখো — verb singular না plural তা নির্দেশ করে কোনটা বসবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এর একটা শব্দ তুলে আনলেও summary-র বাক্যে ব্যাকরণগতভাবে না বসা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর বসিয়ে পুরো বাক্যটা আরেকবার পড়ো — অর্থবহ ও ব্যাকরণসম্মত লাগছে কিনা যাচাই করো"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ভুল অংশ থেকে উত্তর তোলা (passage-এ একই বিষয়ে দুই জায়গায় তথ্য থাকা)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Summary/note-এর আগে-পরের বাক্যের সাথে পুরো প্রসঙ্গ মিলিয়ে দেখো, শুধু একটা শব্দ মিললেই সেটাই উত্তর নয়"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৭.২ Speed Boost — Completion-এ সময় বাঁচানোর কৌশল"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Summary/Note-এর মধ্যে যেসব শব্দ ইতিমধ্যে দেওয়া আছে (ফাঁকা জায়গার আশেপাশে), সেগুলো দিয়েই আগে passage-এ সেই প্রসঙ্গ খুঁজে বের করো — এটাই সবচেয়ে দ্রুত রাস্তা।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ফাঁকা জায়গাগুলো সাধারণত passage-এর ক্রম অনুযায়ীই সাজানো থাকে — প্রথম ফাঁকার উত্তর পেলে, দ্বিতীয় ফাঁকার উত্তর তার কাছাকাছি বা পরের অংশেই খুঁজো, পুরো passage আবার প্রথম থেকে খোঁজার দরকার নেই।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা শব্দ বসিয়ে নিশ্চিত না হলে, প্রশ্নচিহ্ন দিয়ে মার্ক করে এগিয়ে যাও, শেষে ফিরে এসো।"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"PART 4"}]},{"type":"paragraph","content":[{"type":"text","text":"Matching প্রশ্ন"}]},{"type":"paragraph","content":[{"type":"text","text":"Heading, Information ও Feature Matching — তিনটেই আলাদা দক্ষতা চায়"}]}]}'::jsonb, 'published', 'advanced', 10, now());

