  values (v_matching_headings, 'Matching Headings', 'matching-headings-strategy', 'The five-step method, plus how to spot the distractors examiners build in.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৮ — Matching Headings"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৮.১ এই প্রশ্ন আসলে কী মাপে"}]},{"type":"paragraph","content":[{"type":"text","text":"একটা তালিকায় কয়েকটা heading (সংক্ষিপ্ত শিরোনাম) দেওয়া থাকে, এবং প্রতিটা অনুচ্ছেদের (paragraph) জন্য সবচেয়ে উপযুক্ত heading বেছে নিতে হয়। এটা বিস্তারিত তথ্য নয়, পুরো অনুচ্ছেদের মূলভাব (main idea) মাপে।"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে বড় ভুল অনুচ্ছেদের প্রথম বাক্য দেখেই heading বেছে নেওয়া। প্রথম বাক্য প্রায়ই ভূমিকা মাত্র — আসল মূলভাব মাঝে বা শেষে থাকতে পারে। পুরো অনুচ্ছেদের সারমর্ম বুঝে heading বাছতে হবে, একটা বাক্য দেখে নয়। Heading-এ থাকা একটা শব্দ অনুচ্ছেদে দেখেই সেই heading বেছে নেওয়া। Heading list-এ ইচ্ছাকৃতভাবে এমন কিছু heading রাখা হয় যেগুলোতে অনুচ্ছেদের একটা ছোট অংশের সাথে মিল থাকা শব্দ আছে, কিন্তু পুরো অনুচ্ছেদের সাথে মেলে না — এগুলো ফাঁদ (distractor)।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৮.২ পাঁচ ধাপের পদ্ধতি"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Heading list আগে পড়ো — প্রতিটা heading সংক্ষেপে কী বলছে বুঝে নাও। সাধারণত heading-এর সংখ্যা অনুচ্ছেদের চেয়ে বেশি থাকে (কিছু heading ব্যবহৃতই হবে না) — এটা মাথায় রাখো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটা অনুচ্ছেদ Skim করো — প্রথম ও শেষ বাক্য মনোযোগ দিয়ে পড়ো, মাঝেরটা দ্রুত চোখ বুলাও। জিজ্ঞেস করো: \"এই অনুচ্ছেদ মূলত কী নিয়ে?\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজের ভাষায় একটা সংক্ষিপ্ত সারমর্ম মনে মনে তৈরি করো, তারপর সেটার সাথে সবচেয়ে কাছাকাছি heading খোঁজো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"সহজ অনুচ্ছেদগুলো আগে করো — একটাতে আটকে গেলে বাকিগুলো আগে শেষ করো, ব্যবহৃত heading বাদ দিতে দিতে শেষেরগুলো এমনিতেই সহজ হয়ে আসবে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা heading একবারই ব্যবহার হয় (আলাদাভাবে না বলা থাকলে) — তালিকায় টিক দিতে দিতে এগোও যাতে দুইবার ব্যবহার না হয়ে যায়।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৮.৩ Worked Example"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Heading বাছাইয়ের যুক্তি Heading List: i. The economic cost of the crisis ii. A surprising early warning ignored by officials iii. How other countries responded differently iv. The origins of the problem v. Long-term consequences for public health  Paragraph: \"Few could have predicted, in the years leading up to the crisis, just how severe its impact would become. Yet as early as a decade earlier, a handful of researchers had already published findings suggesting the underlying trend, only for their warnings to be dismissed by policymakers as overly cautious and unlikely to materialise.\"  → অনুচ্ছেদটা \"predicted\" আর \"warnings...dismissed\" নিয়ে — এটা কোনো সতর্কতা যা উপেক্ষা করা হয়েছিল। সঠিক Heading: ii (A surprising early warning ignored by officials) (লক্ষ করো: \"iv. origins of the problem\" ভুল উত্তর মনে হতে পারে কারণ এটাও অতীতের কথা বলছে, কিন্তু অনুচ্ছেদের মূল বিষয় \"origin\" নয়, \"ignored warning\" — এটাই ফাঁদ)"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৮.৪ Distractor (ফাঁদ) চেনার উপায়"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ফাঁদের ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কীভাবে চিনবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আংশিক মিল"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Heading-এর একটা শব্দ অনুচ্ছেদে আছে, কিন্তু পুরো heading অনুচ্ছেদের মূলভাব প্রকাশ করছে না"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"খুব সাধারণ (too general)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Heading এত বিস্তৃত যে যেকোনো অনুচ্ছেদের সাথে মানিয়ে যায় — কিন্তু নির্দিষ্টভাবে কোনোটার সাথেই সেরা মিল নয়"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"খুব নির্দিষ্ট (too specific)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Heading অনুচ্ছেদের একটা ছোট উদাহরণ/বিস্তারিত অংশকে নির্দেশ করছে, পুরো অনুচ্ছেদকে নয়"}]}]}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Matching Information
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_matching_information, 'Matching Information', 'matching-information-strategy', 'How paragraph matching differs from matching headings, and what kind of statements to expect.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ৯ — Matching Information (Paragraph Matching)"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৯.১ Matching Headings থেকে পার্থক্য"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":""}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Headings"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Information"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"কী খোঁজে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পুরো অনুচ্ছেদের মূলভাব"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা নির্দিষ্ট তথ্য/উদাহরণ/সংজ্ঞা কোন অনুচ্ছেদে আছে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দিক"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Heading → Paragraph"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement → Paragraph (letter, যেমন A, B, C...)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একবারই ব্যবহার?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"হ্যাঁ, প্রতিটা heading একবার"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"না — একই অনুচ্ছেদ একাধিক statement-এর উত্তর হতে পারে"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"মনে রাখার সহজ উপায় Matching Headings = \"এই অনুচ্ছেদ সামগ্রিকভাবে কী নিয়ে?\" Matching Information = \"এই নির্দিষ্ট তথ্যটা কোথায় লুকানো?\" প্রথমটায় পুরো অনুচ্ছেদ বুঝতে হয়, দ্বিতীয়টায় নির্দিষ্ট বাক্য খুঁজে বের করলেই চলে — পুরো অনুচ্ছেদ বোঝার দরকার নেই।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৯.২ পদ্ধতি"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement-এ থাকা নির্দিষ্ট তথ্যের ধরন চিহ্নিত করো — উদাহরণ, তুলনা, সংখ্যা, কারণ, সংজ্ঞা ইত্যাদি কী খুঁজছ তা স্পষ্ট করো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটা অনুচ্ছেদ দ্রুত স্ক্যান করো, নির্দিষ্ট keyword বা তার paraphrase খুঁজো — পুরোটা পড়ার দরকার নেই।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"যে অনুচ্ছেদে মিল পাও, statement-টা আবার সেই অংশের সাথে মিলিয়ে নিশ্চিত হও।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা অনুচ্ছেদ একাধিক statement-এর উত্তর হতে পারে — তাই আগের উত্তর দেখে এই প্রশ্নের সম্ভাবনা বাদ দিও না।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৯.৩ Worked Example"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Comparison-ভিত্তিক তথ্য খোঁজা Statement: Which paragraph contains a comparison between two different methods?  → Keyword: \"comparison\", \"two different methods\" — passage-এ \"compared with\", \"unlike\", \"whereas\", \"in contrast to\" জাতীয় শব্দ খুঁজতে হবে।  Paragraph C: \"Traditional farming methods, which rely heavily on manual labour, contrast sharply with modern precision agriculture, where sensors and software determine exactly how much water and fertiliser each section of a field requires.\"  → \"contrast sharply with\" — এটাই তুলনা নির্দেশ করছে দুটো পদ্ধতির মধ্যে। উত্তর: Paragraph C"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৯.৪ কী ধরনের Statement সাধারণত আসে"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement-এর ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"যা খুঁজবে"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা উদাহরণ দেওয়া হয়েছে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"for example\", \"such as\", \"for instance\" শব্দ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দুটো জিনিসের তুলনা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"compared with\", \"unlike\", \"whereas\", \"in contrast\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা কারণ ব্যাখ্যা করা হয়েছে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"because\", \"due to\", \"as a result of\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা সংজ্ঞা/ব্যাখ্যা দেওয়া হয়েছে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"refers to\", \"is defined as\", \"means\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা সমস্যার সমাধান প্রস্তাব করা হয়েছে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"\"one solution\", \"to address this\", \"in order to\""}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা সংখ্যা/পরিসংখ্যান উল্লেখ করা হয়েছে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শতাংশ, নির্দিষ্ট সংখ্যা, বছর"}]}]}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Matching Features
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_matching_features, 'Matching Features', 'matching-features-strategy', 'The method for matching features, and how it compares to the other two matching types.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১০ — Matching Features"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১০.১ এই প্রশ্ন আসলে কী মাপে"}]},{"type":"paragraph","content":[{"type":"text","text":"একটা তালিকায় কিছু বৈশিষ্ট্য/মতামত/ঘটনা দেওয়া থাকে, এবং সেগুলোকে নির্দিষ্ট ব্যক্তি, তত্ত্ব, স্থান, বা সময়ের সাথে মেলাতে হয় (যেমন কোন গবেষক কোন মত দিয়েছেন, বা কোন শতাব্দীতে কী ঘটেছে)।"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Features দেখতে যেমন উদাহরণ তালিকা: A. Dr Aisha Rahman     B. Professor James Cole     C. Dr Elena Petrova  Statements: ১. developed the original theory in the 1990s ২. later challenged the theory with new evidence ৩. proposed a modified version combining both views"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১০.২ পদ্ধতি"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটা নাম/বৈশিষ্ট্য passage-এ কোথায় উল্লেখ আছে তা প্রথমে খুঁজে বের করো — নামগুলো (capital letter) স্ক্যান করে সহজেই এই ধাপ দ্রুত করা যায়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটা নামের আশেপাশের বাক্য পড়ে বুঝো সেই ব্যক্তি/জিনিস সম্পর্কে কী বলা হয়েছে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Statement-এর সাথে মিলিয়ে দেখো — এখানেও paraphrase হতে পারে, হুবহু শব্দ নাও মিলতে পারে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"সতর্ক থাকো: একই ব্যক্তির নাম passage-এ একাধিকবার আসতে পারে, বিভিন্ন প্রসঙ্গে — প্রতিটা উল্লেখ আলাদাভাবে পরীক্ষা করো।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সময় বাঁচানোর কৌশল Passage-এ প্রথমে সব নাম হাইলাইট/মার্ক করে ফেলো (মানসিকভাবে বা কাগজে দাগ দিয়ে)। এরপর প্রতিটা statement-এর জন্য শুধু সেই মার্ক করা জায়গাগুলো চেক করলেই হবে, পুরো passage আবার পড়তে হবে না।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১০.৩ তিনটে Matching ধরনের সারসংক্ষেপ"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"মূল প্রশ্ন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কৌশলের মূল কথা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Headings"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এই অনুচ্ছেদ সামগ্রিকভাবে কী নিয়ে?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Skim করো, মূলভাব ধরো, distractor থেকে সাবধান"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Information"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এই নির্দিষ্ট তথ্য কোন অনুচ্ছেদে?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Scan করো, নির্দিষ্ট keyword/উদাহরণ/তুলনা খোঁজো"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Features"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এই বৈশিষ্ট্য কার সাথে সম্পর্কিত?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নাম আগে চিহ্নিত করো, তারপর আশেপাশের তথ্য মেলাও"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"PART 5"}]},{"type":"paragraph","content":[{"type":"text","text":"বাকি প্রশ্নের ধরন"}]},{"type":"paragraph","content":[{"type":"text","text":"Multiple Choice, Short-Answer Questions ও Diagram Labelling"}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Multiple Choice
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_multiple_choice, 'Multiple Choice', 'multiple-choice-strategy', 'The two kinds of multiple choice questions, the method, and common distractor types.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১১ — Multiple Choice"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১১.১ দুই ধরনের Multiple Choice"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বর্ণনা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একটা সঠিক উত্তর বাছাই (A/B/C/D থেকে ১টা)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সবচেয়ে সাধারণ — একটা প্রশ্নের সবচেয়ে ভালো উত্তর বেছে নাও"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একাধিক সঠিক উত্তর বাছাই (৫টা অপশন থেকে ২টা, ইত্যাদি)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নির্দেশনায় স্পষ্ট লেখা থাকবে কয়টা বাছতে হবে — এই সংখ্যা মিস করলে নম্বর কাটা যায়"}]}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১১.২ পদ্ধতি"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্ন (stem) পড়ো, কিন্তু অপশনগুলো এখনই মনোযোগ দিয়ে পড়ো না — আগে প্রশ্ন কী জিজ্ঞেস করছে বুঝে নাও।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ প্রাসঙ্গিক অংশ খুঁজো ও পড়ো — MCQ-তে সাধারণত একটা নির্দিষ্ট অনুচ্ছেদ বা তার একটা অংশ থেকেই উত্তর আসে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজে থেকে একটা সম্ভাব্য উত্তর আন্দাজ করো, তারপর অপশনগুলো দেখো — এতে ভুল অপশনের প্ররোচনায় পড়ার ঝুঁকি কমে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রতিটা অপশন আলাদাভাবে passage-এর সাথে মিলিয়ে দেখো — ভুল অপশনগুলো (distractors) প্রায়ই passage-এর তথ্য দিয়েই তৈরি, কিন্তু সামান্য পরিবর্তিত বা ভুল প্রসঙ্গে ব্যবহৃত।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Elimination পদ্ধতি ব্যবহার করো — স্পষ্ট ভুল অপশনগুলো প্রথমে বাদ দাও, তারপর বাকিগুলোর মধ্যে থেকে বাছো।"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১১.৩ Distractor-এর সাধারণ ধরন"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ফাঁদের ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সংখ্যা সামান্য পরিবর্তিত"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ \"30%\" থাকলে অপশনে \"13%\" বা \"300%\" রাখা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সঠিক তথ্য, ভুল কারণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তথ্যটা ঠিক আছে, কিন্তু কারণ/সম্পর্ক passage-এর সাথে মেলে না"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অতি সাধারণীকরণ (overgeneralisation)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ \"some\" বলা আছে, অপশনে \"all\" বা \"most\" লেখা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সঠিক তথ্য, ভুল ব্যক্তি/স্থান/সময়"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তথ্যটা passage-এ আছে ঠিকই, কিন্তু ভুল ব্যক্তির সাথে জুড়ে দেওয়া"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"মনে রাখার একটা কার্যকর নিয়ম সবচেয়ে ভালো অপশনটা প্রায়ই সবচেয়ে \"নিরাপদ\" বা hedge করা (qualified) ভাষায় লেখা থাকে — passage যদি সতর্কতার সাথে কিছু বলে (may, might, tends to, in some cases), তাহলে যে অপশনটাও একই সতর্কতার সুর বজায় রাখে, সেটাই প্রায়ই সঠিক। যে অপশন অতি নিশ্চিতভাবে (always, definitely, completely) কিছু দাবি করে, সেটা প্রায়ই ভুল।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১১.৪ Worked Example"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Distractor এড়িয়ে সঠিক উত্তর বাছাই Passage অংশ: \"Although early studies suggested that caffeine consumption might impair sleep quality across all age groups, more recent research indicates that the effect varies considerably depending on individual metabolism, with some people showing little to no disruption even after consuming caffeine close to bedtime.\"  Question: According to the passage, the effect of caffeine on sleep A. is the same for everyone regardless of when it is consumed B. has been proven to be minimal in all recent studies C. differs from person to person based on how the body processes it D. only affects people who drink caffeine before bed  → A ভুল (\"varies considerably\" — সবার জন্য এক নয়)। B ভুল (passage বলছে \"some people\", \"all\" নয়)। D ভুল (timing নয়, metabolism মূল কারণ)। C সঠিক — \"varies...depending on individual metabolism\" এর সাথে হুবহু মিলছে। সঠিক উত্তর: C"}]}]}]}'::jsonb, 'published', 'advanced', 10, now());

  -- Short-Answer Questions & Diagram Labelling
  insert into lessons (node_id, title, slug, excerpt, content, status, difficulty, estimated_minutes, published_at)
  values (v_short_answer_diagram_labelling, 'Short-Answer Questions & Diagram Labelling', 'short-answer-and-diagram-labelling', 'How to answer short-answer questions and label diagrams, maps, and plans.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অধ্যায় ১২ — Short-Answer Questions ও Diagram Labelling"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১২.১ Short-Answer Questions"}]},{"type":"paragraph","content":[{"type":"text","text":"এখানে প্রশ্নের উত্তর সরাসরি নিজের ভাষায় নয়, passage থেকে হুবহু তুলে, নির্দিষ্ট word limit মেনে লিখতে হয়।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্নটা কী তথ্য চাইছে বুঝো (কে, কী, কখন, কোথায়, কেন, কতজন)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Word limit মেনে চলো — এখানেও Completion-এর মতো একই নিয়ম কাজ করে (অধ্যায় ৬ দেখো)।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ সেই নির্দিষ্ট তথ্য (সাধারণত একটা noun phrase বা সংখ্যা) স্ক্যান করে খুঁজো।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"উত্তর হুবহু passage থেকে কপি করো, নিজে বাক্য বানিয়ে লিখো না।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Short-Answer-এর সংক্ষিপ্ততা Passage: \"The research team collected water samples from twelve different rivers across three continents over a two-year period.\" Question: How many rivers were sampled in the study? উত্তর: twelve (rivers) — শুধু সংখ্যাটাই যথেষ্ট, পুরো বাক্য লেখার দরকার নেই"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"সংক্ষিপ্ত রাখাই মূল কথা Short-Answer-এ যতটুকু জিজ্ঞেস করা হয়েছে ঠিক ততটুকুই লেখো। \"How many rivers?\" প্রশ্নে \"twelve rivers were sampled\" লেখার দরকার নেই — শুধু \"twelve\" বা \"twelve rivers\" যথেষ্ট, এবং এতে word limit ভাঙার ঝুঁকিও কমে।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১২.২ Diagram / Map / Plan Labelling"}]},{"type":"paragraph","content":[{"type":"text","text":"একটা ছবি, মানচিত্র, বা প্রক্রিয়ার নকশা দেওয়া থাকে, এবং passage-এর বর্ণনা পড়ে সেই ছবির বিভিন্ন অংশে সঠিক লেবেল বসাতে হয়। এই ধরনের প্রশ্ন সব টেস্টে থাকে না, কিন্তু আসলে এটা অনেকের কাছে সহজতম মনে হয় কারণ ছবিটা visualize করতে সাহায্য করে।"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ছবিটা প্রথমে ভালো করে দেখো — কী ধরনের বস্তু/প্রক্রিয়া/স্থান এটা বুঝে নাও।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Passage-এ বর্ণনার ক্রম অনুসরণ করো — সাধারণত বর্ণনা একটা নির্দিষ্ট দিক থেকে শুরু হয় (যেমন বাম থেকে ডানে, বা প্রক্রিয়ার শুরু থেকে শেষ পর্যন্ত), এবং লেবেলগুলোও সেই ক্রমেই সাজানো থাকে।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Spatial শব্দগুলো (আশেপাশে, উপরে, নিচে নির্দেশক) চিহ্নিত করো — above, below, next to, adjacent to, opposite, to the left/right of, at the top/bottom of ইত্যাদি শব্দগুলোই একটা অংশ থেকে আরেকটা অংশে যাওয়ার পথ দেখায়।"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ছবির প্রতিটা অংশ passage-এর বর্ণনার সাথে মিলিয়ে confirm করো — শুধু একটা শব্দ মিললেই যথেষ্ট নয়, চারপাশের বর্ণনাও মিলতে হবে।"}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Diagram Labelling-এ সবচেয়ে বড় সুবিধা এই প্রশ্নের ধরনে প্রায়ই passage-এর একটা নির্দিষ্ট অনুচ্ছেদই পুরো বর্ণনা বহন করে — তাই একবার সেই অনুচ্ছেদ খুঁজে পেলে, বাকি সব উত্তর কাছাকাছি জায়গাতেই পাওয়া যায়। পুরো passage খোঁজাখুঁজি করার দরকার নেই।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"১২.৩ Part 2–5 সারসংক্ষেপ — একটা Quick Reference Card"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"প্রশ্নের ধরন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"এক লাইনে কৌশল"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"True/False/Not Given"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তথ্য পুরোপুরি মিললে True, উল্টো হলে False, উল্লেখই না থাকলে Not Given"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes/No/Not Given"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"লেখকের নিজের মত (উদ্ধৃত মত নয়) statement-এর সাথে মেলাও"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sentence/Summary/Note/Table Completion"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Word limit মেনে, passage থেকে হুবহু শব্দ বসাও, grammar মিলিয়ে নাও"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Headings"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পুরো অনুচ্ছেদের মূলভাব ধরো, একটা শব্দ দেখে বিভ্রান্ত হয়ো না"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Information"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নির্দিষ্ট তথ্য (উদাহরণ/তুলনা/কারণ) কোন অনুচ্ছেদে তা স্ক্যান করে খুঁজো"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Matching Features"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নাম আগে চিহ্নিত করো, তারপর প্রতিটা statement মেলাও"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Multiple Choice"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"নিজে আগে আন্দাজ করো, তারপর elimination দিয়ে ভুল অপশন বাদ দাও"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Short-Answer Questions"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"যতটুকু জিজ্ঞেস ততটুকুই লেখো, word limit মেনে হুবহু কপি করো"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Diagram/Map Labelling"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Spatial শব্দ অনুসরণ করে ক্রম ধরে এগোও"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"PART 6"}]},{"type":"paragraph","content":[{"type":"text","text":"৫টি সম্পূর্ণ Practice Test"}]},{"type":"paragraph","content":[{"type":"text","text":"প্রতিটি টেস্টে ৩টি passage, ৪০টি প্রশ্ন — ২০ মিনিট করে টাইমার সেট করে অনুশীলন করো"}]}]}'::jsonb, 'published', 'advanced', 10, now());

